package com.victor.kodiakmaps

import com.victor.kodiakmaps.core.KFeature
import com.victor.kodiakmaps.core.KGeo
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** v1.5.3: features traced from the georeferenced 1965 Navy General Development Map sheets (mil_hist2.py, poi/hist2/). */
class Hist1965Test {
    companion object {
        /** generated by mil_hist2.py — per georeferenced sheet (s9 = map9a–9d joined) */
        val COUNTS = mapOf("s9" to 108, "map10c" to 9, "map8a" to 12, "map8d" to 31, "map15" to 11, "map7c" to 7, "map7b" to 1, "map6a" to 47, "map6b" to 6, "map5a" to 2, "map23d" to 1)
        val SHEETS = COUNTS.keys
    }
    private val text = File("src/main/assets/kodiak/poi.geojson").readText()
    private val mil = KGeo.parse(text).filter { it.k == "poi_mil" }
    private fun id(f: KFeature) = f.props.optString("id")
    private fun rows(f: KFeature) = f.props.optString("rows").split('\u001f').associate { it.substringBefore('\u001e') to it.substringAfter('\u001e') }
    private val h = mil.filter { id(it).startsWith("milh_") && it.props.optString("src_map") in SHEETS }
    private fun allPts(f: KFeature) = listOfNotNull(f.point) + f.lines.flatten() + f.polys.flatten()

    @Test fun countsPerSheet() {
        assertEquals(COUNTS, h.groupingBy { it.props.optString("src_map") }.eachCount())
        assertEquals(h.size, h.map { id(it) }.toSet().size)
    }

    @Test fun sameCardFormatAndStyleAs152() {
        h.forEach { f ->
            val r = rows(f)
            assertEquals(f.title, "Summary", f.props.optString("rows").substringBefore('\u001e'))
            listOf("On the map", "Source map", "Approx. accuracy", "How it was placed").forEach { assertTrue("${f.title} $it", r.containsKey(it)) }
            assertEquals("kadiak.org (Kodiak Historical Army/Navy site)", r["Source"])
            val acc = f.props.getInt("acc_m"); assertTrue(acc in 20..100); assertTrue(r["Approx. accuracy"]!!.startsWith("± $acc m"))
            assertEquals("map", f.props.optString("cat")); assertEquals("#8D6E63", f.props.optString("color"))
            assertTrue(f.props.optString("cat_label").startsWith("Military history · from an old map · "))
            assertEquals(f.title, f.props.optString("shape") == "pt", f.props.has("detail"))
            assertFalse(f.props.has("imgs") || f.props.has("ovl"))
        }
    }

    @Test fun placedOnTheNavyBase() {
        // sheets 3, 6–10, 15: Kodiak road system (main base to Bells Flats / Commsta), not Chiniak
        h.filter { it.props.optString("src_map") != "map23d" }.forEach { f -> allPts(f).forEach { p -> assertTrue("${f.title} $p", p[0] in 57.60..57.82 && p[1] in -152.70..-152.30) } }
        // sheet 23: Miller Field / Cape Chiniak
        h.filter { it.props.optString("src_map") == "map23d" }.forEach { f -> allPts(f).forEach { p -> assertTrue("${f.title} $p", p[0] in 57.59..57.65 && p[1] in -152.23..-152.12) } }
        val s9 = h.filter { it.props.optString("src_map") in setOf("s9", "map10c") }
        s9.forEach { f -> allPts(f).forEach { p -> assertTrue("${f.title} $p", p[0] in 57.70..57.80 && p[1] in -152.60..-152.42) } }
    }

    @Test fun structureListOnlyWhenNumberAndGridAgree() {
        val links = JSONObject(text).getJSONObject("meta").getJSONArray("mil_hist_1965_links")
        for (i in 0 until links.length()) {
            val l = links.getJSONObject(i); val t = l.getString("feature")
            val f = h.first { it.title == t }; val what = rows(f)["What it was"] ?: ""
            when (l.getString("link")) {
                "yes", "tent" -> assertTrue(t, what.contains("1965 list: ${l.getString("num")} — "))
                else -> assertFalse(t, what.contains("1965 list: ${l.getString("num")} — "))
            }
        }
        fun s(t: String) = rows(h.first { it.title == t })["Summary"]!!
        assertTrue(s("Bldg A-1647").startsWith("Harbor Defense Command Post"))
        assertTrue(s("Bldg 20").startsWith("20: a/c overhaul & repair"))
        assertTrue(s("Bldg 15?").contains("maintenance hangar"))
        assertTrue(rows(h.first { it.title == "Bldg 15?" })["What it was"]!!.contains("— likely, from the label and site"))
        assertTrue(s("Bldg 6").contains("not linked"))
        assertTrue(h.any { it.title.startsWith("Aviation gasoline tank farm") })
        assertTrue(links.let { l -> (0 until l.length()).any { l.getJSONObject(it).getString("feature") == "Bldg 148" && l.getJSONObject(it).getString("link") == "yes" } })
    }

    @Test fun notPlacedListUpdated() {
        val d = JSONObject(text).getJSONObject("meta").getJSONArray("mil_hist_not_placed")
        val maps = (0 until d.length()).map { d.getJSONObject(it).getString("map") }
        assertTrue(maps.none { it.startsWith("map5a–map9d") })
        assertTrue(maps.any { it.contains("map23a") })
        assertTrue(maps.none { it.contains("map6a") || it.contains("map8a") || it.contains("map15") || it.contains("map5a") })
    }
}
